class Solution {
public:
    int racecar(int target) {
        vector<int> dp(target + 1, 0);
        for (int t = 1; t <= target; t++) {
            int k = 32 - __builtin_clz(t);
            if (t == (1 << k) - 1) {
                dp[t] = k;
                continue;
            }
            // Overshoot: k A's to 2^k - 1, then R, then solve remaining
            dp[t] = k + 1 + dp[(1 << k) - 1 - t];
            // Undershoot: (k-1) A's to 2^(k-1)-1, R, m A's backward, R, solve remaining
            for (int m = 0; m < k - 1; m++) {
                dp[t] = min(dp[t], k + m + 1 + dp[t - (1 << (k - 1)) + (1 << m)]);
            }
        }
        return dp[target];
    }
};
